# PBS (Proxmox Backup Server) client backup sidecar
# Provides automated backup of container data to PBS
{ config, lib, pkgs, ... }:

with lib;

let
  cfg = config.services.lxc-sidecars.backup;
in
{
  options.services.lxc-sidecars.backup = {
    enable = mkEnableOption "PBS backup sidecar";

    schedule = mkOption {
      type = types.str;
      default = "weekly";
      description = "Backup schedule (daily, weekly, monthly, or systemd calendar spec)";
    };

    paths = mkOption {
      type = types.listOf types.str;
      default = [ ];
      description = "Paths to backup";
    };

    exclude = mkOption {
      type = types.listOf types.str;
      default = [ ];
      description = "Patterns to exclude from backup";
    };

    pbsRepository = mkOption {
      type = types.str;
      default = "pbs@pbs!pbs-client@192.168.86.100:containers";
      description = "PBS repository string";
    };

    pbsNamespace = mkOption {
      type = types.nullOr types.str;
      default = null;
      description = "PBS namespace for backup organization";
    };

    healthcheckUuid = mkOption {
      type = types.nullOr types.str;
      default = null;
      description = "Healthchecks.io UUID for backup monitoring";
    };

    preBackupCommand = mkOption {
      type = types.nullOr types.str;
      default = null;
      description = "Command to run before backup (e.g., database dump)";
    };

    postBackupCommand = mkOption {
      type = types.nullOr types.str;
      default = null;
      description = "Command to run after backup";
    };

    backupId = mkOption {
      type = types.str;
      default = config.networking.hostName;
      description = "Backup ID (defaults to hostname)";
    };
  };

  config = mkIf cfg.enable {
    # Install proxmox-backup-client
    environment.systemPackages = [ pkgs.proxmox-backup-client ];

    # PBS credentials from sops
    sops.secrets."pbs/encryption-key" = {
      path = "/etc/proxmox-backup/encryption-key.json";
    };
    sops.secrets."pbs/password" = { };

    # Convert schedule shorthand to systemd calendar spec
    systemd.timers."pbs-backup" = {
      wantedBy = [ "timers.target" ];
      timerConfig = {
        OnCalendar =
          if cfg.schedule == "daily" then "*-*-* 02:00:00"
          else if cfg.schedule == "weekly" then "Sun *-*-* 02:00:00"
          else if cfg.schedule == "monthly" then "*-*-01 02:00:00"
          else cfg.schedule;
        Persistent = true;
        RandomizedDelaySec = "1h";
      };
    };

    systemd.services."pbs-backup" = {
      description = "PBS Backup";
      after = [ "network-online.target" ];
      wants = [ "network-online.target" ];

      environment = {
        PBS_REPOSITORY = cfg.pbsRepository;
        PBS_ENCRYPTION_PASSWORD = ""; # Key file is used instead
      };

      script =
        let
          excludeArgs = concatMapStringsSep " " (p: "--exclude '${p}'") cfg.exclude;
          pathArgs = concatMapStringsSep " " (p: "${p}.pxar:${p}") cfg.paths;
          namespaceArg = optionalString (cfg.pbsNamespace != null) "--ns ${cfg.pbsNamespace}";
          healthcheckStart = optionalString (cfg.healthcheckUuid != null)
            "${pkgs.curl}/bin/curl -fsS -m 10 --retry 5 https://health.bhamra.casa/ping/${cfg.healthcheckUuid}/start || true";
          healthcheckSuccess = optionalString (cfg.healthcheckUuid != null)
            "${pkgs.curl}/bin/curl -fsS -m 10 --retry 5 https://health.bhamra.casa/ping/${cfg.healthcheckUuid} || true";
          healthcheckFail = optionalString (cfg.healthcheckUuid != null)
            "${pkgs.curl}/bin/curl -fsS -m 10 --retry 5 https://health.bhamra.casa/ping/${cfg.healthcheckUuid}/fail || true";
          preBackup = optionalString (cfg.preBackupCommand != null) cfg.preBackupCommand;
          postBackup = optionalString (cfg.postBackupCommand != null) cfg.postBackupCommand;
        in
        ''
          set -euo pipefail

          # Signal backup start
          ${healthcheckStart}

          # Pre-backup hook
          ${preBackup}

          # Run backup
          export PBS_PASSWORD=$(cat ${config.sops.secrets."pbs/password".path})

          if ${pkgs.proxmox-backup-client}/bin/proxmox-backup-client backup \
            ${pathArgs} \
            ${excludeArgs} \
            ${namespaceArg} \
            --keyfile /etc/proxmox-backup/encryption-key.json \
            --backup-id ${cfg.backupId}; then

            # Post-backup hook
            ${postBackup}

            # Signal success
            ${healthcheckSuccess}
          else
            # Signal failure
            ${healthcheckFail}
            exit 1
          fi
        '';

      serviceConfig = {
        Type = "oneshot";
        Nice = 19;
        IOSchedulingClass = "idle";
      };
    };
  };
}
